<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demo TESTIGN</title><link rel="stylesheet" href="demo-style.css?v=4"><style>.board{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.col h3{margin-top:0}.item{margin:12px 0}.bar{height:10px;background:#edf1f5;border-radius:99px;overflow:hidden}.bar span{display:block;height:100%;background:#2f5f8f;border-radius:99px}@media(max-width:850px){.board{grid-template-columns:1fr}}</style></head><body><nav class="demo-nav"><div class="demo-nav-inner"><a class="brand" href="../index.php#proyectos">← Volver al portafolio</a><a class="btn primary" href="#">GitHub pendiente</a></div></nav><main class="wrap"><section class="hero"><div><span class="kicker">Testing y documentación</span><h1>T E S T I G N</h1><p>Demo de tablero para ordenar criterios, evidencias y progreso de una evaluación técnica con enfoque visual y simple.</p></div><div class="panel"><h2>Avance general</h2><div class="bar"><span id="bar" style="width:72%"></span></div><p><strong id="pct">72%</strong> completado</p><button class="btn primary" onclick="advance()">Simular avance</button></div></section><section class="board"><div class="panel col"><h3>Criterios</h3><div class="card item">Criterio 05 <span class="pill">Listo</span></div><div class="card item">Criterio 06 <span class="pill">En proceso</span></div></div><div class="panel col"><h3>Evidencias</h3><div class="card item">Capturas</div><div class="card item">Guion</div><div class="card item">Documento final</div></div><div class="panel col"><h3>Revisión</h3><div class="card item">Coherencia visual</div><div class="card item">Entrega final</div></div></section></main><script>let v=72;function advance(){v=Math.min(100,v+7);bar.style.width=v+'%';pct.textContent=v+'%'}</script></body></html>
